INSERT INTO "public"."documents" ("id", "celex_number", "title", "document_type", "publication_date", "official_url", "category", "summary", "keywords", "languages", "highlights", "tags", "search_id", "created_at", "updated_at") VALUES ('0d9f8793-a0a6-4af3-8ed7-1aa631d0e8d5', '32021R1060', 'Regulation (EU) 2021/1060 of the European Parliament and of the Council of 24 June 2021 laying down common provisions on the European Regional Development Fund, the European Social Fund Plus, the Cohesion Fund, the Just Transition Fund and the European Maritime, Fisheries and Aquaculture Fund and financial rules for those and for the Asylum, Migration and Integration Fund, the Internal Security Fund and the Instrument for Financial Support for Border Management and Visa Policy', 'Regulation', '2021-06-30', 'http://data.europa.eu/eli/reg/2021/1060/oj', 'Regional Development', 'Regulation (EU) 2021/1060 establishes common provisions for various EU funds, including the European Regional Development Fund and the Just Transition Fund. It aims to enhance financial support for cohesion and social inclusion across member states while promoting regional development and sustainability.', ARRAY["sustainability","baltic tourism"], ARRAY["BG","ES","CS","DA","DE","ET","EL","EN","FR","GA","HR","IT","LV","LT","HU","MT","NL","PL","PT","RO","SK","SL","FI","SV"], ARRAY["Defines common rules for multiple EU funds including the European Social Fund Plus and the Cohesion Fund.","Enhances support for regions transitioning towards sustainability and for achieving economic, social, and territorial cohesion.","Sets forth financial regulations to ensure effective and transparent use of EU funds."], ARRAY["Cohesion Policy","Sustainability","EU Funding","Social Inclusion","Regional Development"], 'qkn6epbk', '2025-12-17 23:05:10.648+00', '2025-12-17 23:09:44.892844+00'), ('1704b56c-d531-4229-9ccc-9838604461fb', '32025R2454', 'Council Regulation (EU) 2025/2454 of 1 December 2025 fixing the fishing opportunities for certain fish stocks and groups of fish stocks applicable in the Baltic Sea for 2026 and amending Regulation (EU) 2025/202 as regards certain fishing opportunities in other waters', 'Regulation', '2025-12-02', 'http://data.europa.eu/eli/reg/2025/2454/oj', 'Fisheries Law', 'Council Regulation (EU) 2025/2454 establishes fishing opportunities for specific fish stocks in the Baltic Sea for the year 2026 and makes amendments to previous regulations regarding fishing in other waters. The regulation aims to ensure sustainable fishing practices while managing marine resources effectively.', ARRAY["sustainability","baltic tourism"], ARRAY["BG","ES","CS","DA","DE","ET","EL","EN","FR","GA","HR","IT","LV","LT","HU","MT","NL","PL","PT","RO","SK","SL","FI","SV"], ARRAY["Sets fishing quotas for various fish stocks in the Baltic Sea for 2026.","Amends existing Regulation (EU) 2025/202 to include additional fishing opportunities.","Focuses on sustainable management of fish stocks.","Aligns with the EU's Common Fisheries Policy objectives.","Provides a legal framework for monitoring and enforcement of fishing regulations."], ARRAY["sustainable fishing","Baltic Sea","fishing quotas","EU regulations","marine resources","Common Fisheries Policy","fisheries management"], 'qkn6epbk', '2025-12-17 23:05:10.648+00', '2025-12-17 23:09:44.938344+00'), ('31046b68-fd93-4887-ad8b-beec0193c7bc', '32024R2903', 'Council Regulation (EU) 2024/2903 of 18 November 2024 fixing the fishing opportunities for certain fish stocks and groups of fish stocks applicable in the Baltic Sea for 2025 and amending Regulation (EU) 2024/257 as regards certain fishing opportunities in other waters', 'Regulation', '2024-11-19', 'http://data.europa.eu/eli/reg/2024/2903/oj', 'Environmental Law', 'Council Regulation (EU) 2024/2903 aims to establish fishing opportunities for various fish stock categories in the Baltic Sea for the year 2025, ensuring sustainable management of marine resources. The regulation also amends previous regulations concerning fishing in other waters.', ARRAY["sustainability","baltic tourism"], ARRAY["BG","ES","CS","DA","DE","ET","EL","EN","FR","GA","HR","IT","LV","LT","HU","MT","NL","PL","PT","RO","SK","SL","FI","SV"], ARRAY["Sets fishing quotas for specific fish stocks in the Baltic Sea for 2025.","Amends Regulation (EU) 2024/257 related to fishing opportunities in other water bodies.","Promotes sustainable fishing practices to balance marine biodiversity and economic interests.","Introduces in-force dates and compliance requirements for the fishing industry.","Outlines penalties for non-compliance with established quotas."], ARRAY["fishing regulation","sustainable practices","marine resources","Baltic Sea","fisheries management","EU legislation","biological diversity","quota system"], 'searchIdTest01', '2025-12-18 07:48:49.932+00', '2025-12-18 07:48:50.754931+00'), ('74d19535-febe-4b80-9cb3-c4d70e1cea76', '32024L3101', 'Directive (EU) 2024/3101 of the European Parliament and of the Council of 27 November 2024 amending Directive 2005/35/EC as regards ship-source pollution and on the introduction of administrative penalties for infringements (Text with EEA relevance)', 'Directive', '2024-12-16', 'http://data.europa.eu/eli/dir/2024/3101/oj', 'Environmental Law', 'Directive (EU) 2024/3101 aims to amend Directive 2005/35/EC by addressing ship-source pollution and introducing administrative penalties for related infringements. This directive is intended to enhance compliance and enforcement mechanisms within the EU for maritime pollution issues.', ARRAY["sustainability","baltic tourism"], ARRAY["BG","ES","CS","DA","DE","ET","EL","EN","FR","GA","HR","IT","LV","LT","HU","MT","NL","PL","PT","RO","SK","SL","FI","SV"], ARRAY["Introduction of administrative penalties for ship-source pollution infringements.","Amendments to strengthen existing provisions concerning environmental protection at sea.","Enhancement of compliance measures for ship operators and relevant authorities."], ARRAY["ship-source pollution","administrative penalties","maritime law","EU legislation","environmental protection","compliance","pollution control"], 'searchIdTest01', '2025-12-18 07:48:49.932+00', '2025-12-18 07:48:50.753434+00'), ('8b066435-2190-4800-9d06-ebf90e3ecc93', '32024R1991', 'Regulation (EU) 2024/1991 of the European Parliament and of the Council of 24 June 2024 on nature restoration and amending Regulation (EU) 2022/869 (Text with EEA relevance)', 'Regulation', '2024-07-29', 'http://data.europa.eu/eli/reg/2024/1991/oj', 'Environmental Law', 'Regulation (EU) 2024/1991 aims to enhance nature restoration efforts within the EU while amending previous legislation on environmental protection. It establishes frameworks for member states to implement effective restoration initiatives and contributes to the EU''s biodiversity objectives.', ARRAY["sustainability","baltic tourism"], ARRAY["BG","ES","CS","DA","DE","ET","EL","EN","FR","GA","HR","IT","LV","LT","HU","MT","NL","PL","PT","RO","SK","SL","FI","SV"], ARRAY["Introduces mandatory objectives and timelines for nature restoration in EU member states.","Defines measures to assess and monitor progress in ecological recovery.","Amends Regulation (EU) 2022/869 to align with new restoration targets.","Promotes community and stakeholder involvement in restoration activities.","Incorporates strategies for resilience against climate change impacts."], ARRAY["biodiversity","nature restoration","environmental protection","EU regulations","sustainable development"], 'qkn6epbk', '2025-12-17 23:05:10.648+00', '2025-12-17 23:09:44.95004+00'), ('ff30bbc5-ce19-4ef0-a9f8-8474df4acf13', '32025R2196', 'Commission Implementing Regulation (EU) 2025/2196 of 17 October 2025 laying down detailed rules for the implementation of Council Regulation (EC) No 1224/2009 as regards access to waters and resources, control of fisheries, surveillance, inspection and enforcement, deduction of quotas and fishing efforts, data and information, and repealing Commission Implementing Regulation (EU) No 404/2011', 'Regulation', '2025-11-12', 'http://data.europa.eu/eli/reg_impl/2025/2196/oj', 'Fisheries Law', 'The Commission Implementing Regulation (EU) 2025/2196 establishes detailed implementation rules for Council Regulation (EC) No 1224/2009, focusing on fisheries management including access to waters, control measures, and data requirements. It aims to ensure effective surveillance, inspection, and enforcement within the fisheries sector, while repealing the previous implementing regulation from 2011.', ARRAY["sustainability","baltic tourism"], ARRAY["BG","ES","CS","DA","DE","ET","EL","EN","FR","GA","HR","IT","LV","LT","HU","MT","NL","PL","PT","RO","SK","SL","FI","SV"], ARRAY["Sets rules for access to fisheries resources and waters.","Introduces measures for control, inspection, and enforcement of fishing activities.","Establishes protocols for the deduction of quotas and management of fishing efforts.","Mandates data collection and information reporting for better fisheries management.","Repeals the previous Commission Implementing Regulation (EU) No 404/2011."], ARRAY["fishing management","EU regulations","sustainability","fisheries control","data reporting"], 'searchIdTest01', '2025-12-18 07:48:49.932+00', '2025-12-18 07:48:50.753434+00');